116	export async function login(
117	  prev: any,
118	  formData: FormData,
119	): Promise<{ error?: string; needs2fa?: boolean }> {
120	  const parsed = credsSchema.safeParse({
121	    email: formData.get("email"),
122	    password: formData.get("password"),
123	  });
124	  if (!parsed.success) return { error: "Invalid email or password." };
125	
126	  // App-level throttle per email+IP over a 15 min window. The max-attempts cap is
127	  // admin-configurable (`login_ratelimit_max`, default 10) rather than hardcoded.
128	  const hdrs = await headers();
129	  const ip = (hdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
130	  const rlId = `${parsed.data.email}:${ip}`;
131	  const maxAttempts = Math.max(1, await getSettingInt("login_ratelimit_max", 10));
132	  const rl = checkRateLimit(`login:${rlId}`, { max: maxAttempts, windowMs: 15 * 60 * 1000 });
133	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
134	
135	  const user = await db.user.findUnique({ where: { email: parsed.data.email } });
136	  if (!user || !(await bcrypt.compare(parsed.data.password, user.passwordHash))) {
137	    return { error: "Invalid email or password." };
138	  }
139	  if (user.suspended) return { error: "This account is suspended." };
140	
141	  // Two-factor challenge, if enabled on the account.
142	  if (user.totpEnabled) {
143	    const code = String(formData.get("code") ?? "").trim();
144	    if (!code) return { error: "Enter your 2FA code to continue.", needs2fa: true };
145	    if (!(await verifyTotpForUser(user.id, code))) {
146	      return { error: "Invalid 2FA code.", needs2fa: true };
147	    }
148	  }
149	
150	  resetRateLimit(`login:${rlId}`);
151	  await audit(user.id, "user.login");
152	  await createSession(user.id);
153	  redirect(user.role === "ADMIN" ? "/admin" : "/dashboard");
154	}
