109	    });
110	    const { sendMail, emails } = await import("./mailer");
111	    const link = `${process.env.APP_URL ?? "https://revsports.ca"}/reset-password?token=${token}`;
112	    const tpl = emails.passwordReset(link);
113	    await sendMail({ to: email, subject: tpl.subject, html: tpl.html });
114	    await db.auditLog.create({ data: { userId: user.id, action: "user.password_reset_request" } });
115	  }
