119	export async function resetPassword(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
120	  const token = String(formData.get("token") ?? "");
121	  const password = String(formData.get("password") ?? "");
122	  if (password.length < 8) return { error: "Password must be at least 8 characters." };
123	  const { createHash } = await import("node:crypto");
124	  const tokenHash = createHash("sha256").update(token).digest("hex");
125	  const row = await db.passwordResetToken.findUnique({ where: { tokenHash } });
126	  if (!row || row.usedAt || row.expiresAt < new Date()) {
127	    return { error: "This reset link is invalid or has expired. Request a new one." };
128	  }
129	  await db.$transaction([
130	    db.user.update({ where: { id: row.userId }, data: { passwordHash: await bcrypt.hash(password, 12) } }),
131	    db.passwordResetToken.update({ where: { id: row.id }, data: { usedAt: new Date() } }),
132	    db.auditLog.create({ data: { userId: row.userId, action: "user.password_reset_complete" } }),
133	  ]);
134	  return { ok: true };
135	}
