50	/**
51	 * Order a new block storage volume: debit the wallet up-front (one month) and
52	 * create the Volume row PENDING plus a VOLUME_CREATE job. The job flips it to
53	 * DETACHED (available to attach). No physical disk is created until attach.
54	 */
55	export async function orderVolume(
56	  name: string,
57	  sizeGB: number
58	): Promise<{ error?: string; id?: string }> {
59	  const user = await requireUser();
60	
61	  const clean = (name ?? "")
62	    .replace(/[\x00-\x1f\x7f]/g, "")
63	    .replace(/\s+/g, " ")
64	    .trim();
65	  if (clean.length < 2 || clean.length > 40) {
66	    return { error: "Name must be 2–40 characters." };
67	  }
68	  const size = Math.round(Number(sizeGB));
69	  if (!Number.isFinite(size) || size < MIN_GB || size > MAX_GB) {
70	    return { error: `Size must be between ${MIN_GB} and ${MAX_GB} GB.` };
71	  }
72	
73	  const priceCents = await volumePriceCents(size);
74	
75	  let volumeId: string;
76	  try {
77	    volumeId = await db.$transaction(async (tx) => {
78	      await debitWallet(tx, user.id, priceCents);
79	      await tx.walletTransaction.create({
80	        data: {
81	          userId: user.id,
82	          amountCents: -priceCents,
83	          description: `Block storage volume: ${clean} (${size} GB)`,
84	        },
85	      });
86	      const v = await tx.volume.create({
87	        data: {
88	          userId: user.id,
89	          name: clean,
90	          sizeGB: size,
91	          priceCents,
92	          status: "PENDING",
93	          expiresAt: addMonths(new Date(), 1),
94	        },
95	      });
96	      await tx.job.create({ data: { type: "VOLUME_CREATE", payload: { volumeId: v.id } } });
97	      return v.id;
98	    });
99	  } catch (e) {
100	    if (e instanceof InsufficientBalanceError) {
101	      return { error: "Insufficient balance — top up your wallet first." };
102	    }
103	    throw e;
104	  }
105	
106	  await db.auditLog.create({
107	    data: { userId: user.id, action: "volume.order", detail: `${volumeId} ${clean} ${size}GB` },
108	  });
109	  revalidatePath("/dashboard/volumes");
110	  return { id: volumeId };
111	}
