113	/** Attach a DETACHED volume to one of the caller's RUNNING servers. */
114	export async function attachVolume(
115	  volumeId: string,
116	  serverId: string
117	): Promise<{ error?: string }> {
118	  const { user, volume } = await ownedVolume(volumeId);
119	  const { server } = await ownedServer(serverId);
120	
121	  if (volume.status !== "DETACHED") {
122	    return { error: "Only an available (detached) volume can be attached." };
123	  }
124	  if (!server.vmid || server.status !== "RUNNING") {
125	    return { error: "Target server must be running." };
126	  }
127	  // A volume that already holds data physically lives on one server's VM; it can
128	  // only be re-attached there (cross-node disk migration is out of scope).
129	  if (volume.serverId && volume.serverId !== serverId) {
130	    return { error: "This volume holds data on another server. Attach it there, or delete it first." };
131	  }
132	  if (await serverBusy(serverId)) {
133	    return { error: "Another operation is already in progress on this server." };
134	  }
135	
136	  await db.volume.update({ where: { id: volumeId }, data: { serverId } });
137	  await db.job.create({ data: { type: "VOLUME_ATTACH", serverId, payload: { volumeId } } });
138	  await db.auditLog.create({
139	    data: { userId: user.id, action: "volume.attach", detail: `${volumeId} -> ${serverId}` },
140	  });
141	  revalidatePath("/dashboard/volumes");
142	  revalidatePath(`/dashboard/servers/${serverId}`);
143	  return {};
144	}
