8	/**
9	 * Customer SSL certificate management — one-click Let's Encrypt certs for a
10	 * domain the customer has already pointed at their server. Ordering is
11	 * ownership-checked here (at enqueue time); the actual issue runs in the worker
12	 * (worker/ssl.ts, SSL_ISSUE) which SSHes to the box and runs certbot — or, in
13	 * SANDBOX/staging, simulates a successful issue.
14	 */
15	
16	// Basic FQDN: one or more dot-separated labels + a 2–24 char alpha TLD. Rejects
17	// wildcards, protocols, ports and paths — certbot wants a bare hostname.
18	const FQDN_RE =
19	  /^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}$/;
20	
21	async function ownedServer(serverId: string) {
22	  const user = await requireUser();
23	  const server = await db.server.findUnique({ where: { id: serverId } });
24	  if (!server) throw new Error("Not found");
25	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
26	  return { user, server };
27	}
28	
29	async function ownedCertificate(id: string) {
30	  const user = await requireUser();
31	  const cert = await db.sslCertificate.findUnique({ where: { id } });
32	  if (!cert) throw new Error("Not found");
33	  if (cert.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
34	  return { user, cert };
35	}
36	
37	/** All of the current user's SSL certificates, newest first. */
38	export async function listCertificates(): Promise<SslCertificate[]> {
39	  const user = await requireUser();
40	  return db.sslCertificate.findMany({
41	    where: { userId: user.id },
42	    orderBy: { createdAt: "desc" },
43	  });
44	}
45	
46	/**
47	 * Request a one-click Let's Encrypt certificate for `domain` on one of the
48	 * caller's servers. Validates the domain, checks server ownership, creates a
49	 * PENDING SslCertificate row and enqueues an SSL_ISSUE job (cert id in payload).
50	 */
51	export async function requestCertificate(
52	  serverId: string,
53	  domain: string
54	): Promise<{ error?: string; id?: string }> {
55	  let ctx;
56	  try {
57	    ctx = await ownedServer(serverId);
58	  } catch (e: any) {
59	    return { error: e.message };
60	  }
61	  const { user, server } = ctx;
62	
63	  const clean = String(domain ?? "").toLowerCase().trim().replace(/\.$/, "");
64	  if (!FQDN_RE.test(clean)) {
65	    return { error: "Enter a valid domain name (e.g. app.example.com) — no protocol, port or wildcard." };
66	  }
67	
68	  // One active/in-flight cert per (user, domain): don't let a customer stack
69	  // duplicate issue jobs for the same hostname.
70	  const existing = await db.sslCertificate.findFirst({
71	    where: { userId: user.id, domain: clean, status: { in: ["PENDING", "ISSUING", "ACTIVE"] } },
72	  });
73	  if (existing) {
74	    return {
75	      error:
76	        existing.status === "ACTIVE"
77	          ? `You already have an active certificate for ${clean}.`
78	          : `A certificate for ${clean} is already being issued.`,
79	    };
80	  }
81	
82	  const cert = await db.sslCertificate.create({
83	    data: {
84	      userId: user.id,
85	      serverId: server.id,
86	      domain: clean,
87	      status: "PENDING",
88	      issuer: "letsencrypt",
89	    },
90	  });
91	  await db.job.create({
92	    data: { type: "SSL_ISSUE", serverId: server.id, payload: { certId: cert.id } },
93	  });
94	  await db.auditLog.create({
95	    data: { userId: user.id, action: "ssl.request", detail: `${clean} on ${server.hostname}` },
96	  });
97	  revalidatePath("/dashboard/ssl");
98	  return { id: cert.id };
99	}
100	
101	/** Permanently remove a certificate record (owner only). */
102	export async function deleteCertificate(id: string): Promise<{ error?: string }> {
103	  let ctx;
104	  try {
105	    ctx = await ownedCertificate(id);
106	  } catch (e: any) {
107	    return { error: e.message };
108	  }
109	  if (ctx.cert.status === "ISSUING") {
110	    return { error: "This certificate is currently being issued — try again in a moment." };
111	  }
112	  await db.sslCertificate.delete({ where: { id } });
113	  await db.auditLog.create({
114	    data: { userId: ctx.user.id, action: "ssl.delete", detail: `${ctx.cert.domain}` },
115	  });
116	  revalidatePath("/dashboard/ssl");
117	  return {};
118	}
119	
120	/** Flip automatic renewal on/off for a certificate (owner only). */
121	export async function toggleAutoRenew(id: string): Promise<{ error?: string }> {
122	  let ctx;
123	  try {
124	    ctx = await ownedCertificate(id);
125	  } catch (e: any) {
126	    return { error: e.message };
127	  }
128	  await db.sslCertificate.update({
129	    where: { id },
130	    data: { autoRenew: !ctx.cert.autoRenew },
131	  });
132	  revalidatePath("/dashboard/ssl");
133	  return {};
134	}
