34	// 256-bit symmetric key for JWE, derived from the app's AUTH_SECRET.
35	// The relay derives the identical key the same way — no extra shared secret.
36	function consoleKey(): Uint8Array {
37	  const secret = process.env.AUTH_SECRET;
38	  if (!secret) throw new Error("AUTH_SECRET is not set");
39	  return new Uint8Array(createHash("sha256").update(`nxeon-console:${secret}`).digest());
40	}
