5	import type { Coupon } from "@prisma/client";
6	import { db } from "./db";
7	import { requireUser, requireAdmin } from "./auth";
8	import { getSettingBool, getSettingInt } from "./settings";
9	import {
10	  describeCoupon,
11	  referralRewardCents,
12	  signupFreeCreditCents,
13	  type CouponApplyResult,
14	} from "./growth";
