100	const couponSchema = z.object({
101	  code: z
102	    .string()
103	    .trim()
104	    .min(3)
105	    .max(32)
106	    .regex(/^[A-Za-z0-9_-]+$/, "Code: letters, digits, dashes/underscores only."),
107	  kind: z.enum(["PERCENT", "FIXED_CENTS", "CREDIT_CENTS"]),
108	  scope: z.enum(["ANY", "TOPUP", "ORDER"]),
109	  value: z.coerce.number().int().min(1).max(1_000_000),
110	  firstTimeOnly: z.coerce.boolean(),
111	  minAmountCents: z.coerce.number().int().min(0).max(10_000_000).optional(),
112	  maxRedemptions: z.coerce.number().int().min(1).max(1_000_000).optional(),
113	  expiresAt: z.string().optional(),
114	  note: z.string().max(200).optional(),
115	});
