117	export async function adminCreateCoupon(
118	  prev: any,
119	  formData: FormData
120	): Promise<{ error?: string; ok?: boolean }> {
121	  const admin = await requireAdmin();
122	  const rawExpires = String(formData.get("expiresAt") ?? "").trim();
123	  const rawMin = String(formData.get("minAmountCents") ?? "").trim();
124	  const rawMax = String(formData.get("maxRedemptions") ?? "").trim();
125	  const parsed = couponSchema.safeParse({
126	    code: formData.get("code"),
127	    kind: formData.get("kind"),
128	    scope: formData.get("scope"),
129	    value: formData.get("value"),
130	    firstTimeOnly: formData.get("firstTimeOnly") === "on",
131	    minAmountCents: rawMin === "" ? undefined : rawMin,
132	    maxRedemptions: rawMax === "" ? undefined : rawMax,
133	    expiresAt: rawExpires === "" ? undefined : rawExpires,
134	    note: formData.get("note") || undefined,
135	  });
136	  if (!parsed.success) {
137	    return { error: parsed.error.issues[0]?.message ?? "Invalid coupon." };
138	  }
139	  const data = parsed.data;
140	  if (data.kind === "PERCENT" && data.value > 100) {
141	    return { error: "Percent value must be between 1 and 100." };
142	  }
143	  const code = data.code.toUpperCase();
144	
145	  const existing = await db.coupon.findUnique({ where: { code } });
146	  if (existing) return { error: "A coupon with that code already exists." };
147	
148	  let expiresAt: Date | null = null;
149	  if (data.expiresAt) {
150	    const d = new Date(data.expiresAt);
151	    if (Number.isNaN(d.getTime())) return { error: "Invalid expiry date." };
152	    expiresAt = d;
153	  }
154	
155	  await db.coupon.create({
156	    data: {
157	      code,
158	      kind: data.kind,
159	      scope: data.scope,
160	      value: data.value,
161	      firstTimeOnly: data.firstTimeOnly,
162	      minAmountCents: data.minAmountCents ?? null,
163	      maxRedemptions: data.maxRedemptions ?? null,
164	      expiresAt,
165	      note: data.note ?? null,
166	    },
167	  });
168	  await db.auditLog.create({
169	    data: { userId: admin.id, action: "admin.coupon_create", detail: code },
170	  });
171	  revalidatePath("/admin/coupons");
172	  return { ok: true };
173	}
