201	// ---------- Signup free credit ----------
202	
203	/**
204	 * Grant the configured signup free credit to a freshly-registered user, once.
205	 * No-op when SIGNUP_FREE_CREDIT_CENTS is 0 or the user already has signup credit.
206	 * Callable from `register` in lib/actions.ts.
207	 */
208	export async function grantSignupCredit(userId: string): Promise<number> {
209	  // Prefer the admin-editable setting (`signup_free_credit_cents`); fall back to
210	  // the legacy SIGNUP_FREE_CREDIT_CENTS env default when the setting is unset.
211	  const cents = await getSettingInt("signup_free_credit_cents", signupFreeCreditCents());
212	  if (cents <= 0) return 0;
213	  const user = await db.user.findUnique({ where: { id: userId } });
214	  if (!user || user.signupCreditCents > 0) return 0;
215	  await db.$transaction([
216	    db.user.update({
217	      where: { id: userId },
218	      data: { balanceCents: { increment: cents }, signupCreditCents: cents },
219	    }),
220	    db.walletTransaction.create({
221	      data: { userId, amountCents: cents, description: "Welcome credit" },
222	    }),
223	  ]);
224	  return cents;
225	}
226	
227	// ---------- Referral rewards ----------
228	
229	/**
230	 * If `userId` was referred and hasn't been rewarded yet, credit BOTH the referred
231	 * user and their referrer with REFERRAL_REWARD_CENTS, exactly once. Guarded by an
232	 * atomic claim on `referralRewardedAt` so concurrent paid actions can't double-pay.
233	 * Callable from `topUp` / `orderServer` in lib/actions.ts after a paid action.
234	 */
235	export async function maybeRewardReferral(userId: string): Promise<boolean> {
236	  const reward = referralRewardCents();
237	  if (reward <= 0) return false;
238	
239	  const user = await db.user.findUnique({ where: { id: userId } });
240	  if (!user || !user.referredById || user.referralRewardedAt) return false;
241	  const referrerId = user.referredById;
242	
243	  // Atomically claim the reward; if another concurrent action already did, bail.
244	  const claim = await db.user.updateMany({
245	    where: { id: userId, referralRewardedAt: null, referredById: { not: null } },
246	    data: { referralRewardedAt: new Date() },
247	  });
248	  if (claim.count === 0) return false;
249	
250	  await db.$transaction([
251	    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: reward } } }),
252	    db.walletTransaction.create({
253	      data: { userId, amountCents: reward, description: "Referral bonus — welcome reward" },
254	    }),
255	    db.user.update({ where: { id: referrerId }, data: { balanceCents: { increment: reward } } }),
256	    db.walletTransaction.create({
257	      data: {
258	        userId: referrerId,
259	        amountCents: reward,
260	        description: "Referral bonus — you referred a friend",
261	      },
262	    }),
263	  ]);
264	
265	  // Best-effort in-app notifications.
266	  try {
267	    await db.notification.createMany({
268	      data: [
269	        {
270	          userId,
271	          title: `You earned a $${(reward / 100).toFixed(2)} referral bonus`,
272	          href: "/dashboard/billing",
273	        },
274	        {
275	          userId: referrerId,
276	          title: `A friend you referred just joined — $${(reward / 100).toFixed(2)} added`,
277	          href: "/dashboard/refer",
278	        },
279	      ],
280	    });
281	  } catch {
282	    /* best-effort */
283	  }
284	  return true;
285	}
