6	/**
7	 * GET /api/chat/[id]?visitorId=…  — fetch a single conversation the widget
8	 * already knows the id of. Strictly scoped: the row is only returned when its
9	 * `visitorId` matches the one supplied, so a visitor can never read another's
10	 * thread by guessing an id. Reading clears the visitor-facing unread flag.
11	 */
12	
13	function clip(v: unknown, max: number): string | null {
14	  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
15	}
16	
17	export async function GET(
18	  req: Request,
19	  { params }: { params: Promise<{ id: string }> }
20	) {
21	  const { id } = await params;
22	  const url = new URL(req.url);
23	  const visitorId = clip(url.searchParams.get("visitorId"), 100);
24	
25	  if (!id || !visitorId) {
26	    return NextResponse.json({ conversation: null, messages: [] });
27	  }
28	
29	  const convo = await db.chatConversation.findFirst({
30	    where: { id, visitorId },
31	    include: { messages: { orderBy: { createdAt: "asc" } } },
32	  });
33	
34	  if (!convo) return NextResponse.json({ conversation: null, messages: [] });
35	
36	  if (convo.unreadForUser) {
37	    await db.chatConversation
38	      .update({ where: { id: convo.id }, data: { unreadForUser: false } })
39	      .catch(() => {});
40	  }
41	
42	  return NextResponse.json({
43	    conversation: {
44	      id: convo.id,
45	      status: convo.status,
46	      name: convo.name,
47	      email: convo.email,
48	    },
49	    messages: convo.messages.map((m) => ({
50	      id: m.id,
51	      sender: m.sender,
52	      body: m.body,
53	      createdAt: m.createdAt.toISOString(),
54	    })),
55	  });
56	}
