3	import { z } from "zod";
4	import { Prisma } from "@prisma/client";
5	import { db } from "./db";
6	
7	export type SubscribeResult = {
8	  ok: boolean;
9	  status: "subscribed" | "already" | "error";
10	  message: string;
11	};
12	
13	const emailSchema = z.email();
14	
15	/**
16	 * Add an email to the newsletter list. Idempotent: a repeat submission of the
17	 * same (case-insensitive) address is reported as "already" rather than an error,
18	 * and the unique constraint is the source of truth against races. No external
19	 * ESP — we just persist the lead for later export.
20	 */
21	export async function subscribe(
22	  email: string,
23	  source = "landing",
24	): Promise<SubscribeResult> {
25	  const raw = typeof email === "string" ? email.trim().toLowerCase() : "";
26	
27	  if (!raw) {
28	    return { ok: false, status: "error", message: "Please enter your email address." };
29	  }
30	  if (raw.length > 200) {
31	    return { ok: false, status: "error", message: "That email address is too long." };
32	  }
33	
34	  const parsed = emailSchema.safeParse(raw);
35	  if (!parsed.success) {
36	    return { ok: false, status: "error", message: "That doesn’t look like a valid email." };
37	  }
38	  const value = parsed.data;
39	
40	  const cleanSource = (typeof source === "string" ? source.trim() : "").slice(0, 60) || "landing";
41	
42	  const existing = await db.newsletterSubscriber.findUnique({ where: { email: value } });
43	  if (existing) {
44	    return {
45	      ok: true,
46	      status: "already",
47	      message: "You’re already on the list — thanks for sticking around!",
48	    };
49	  }
50	
51	  try {
52	    await db.newsletterSubscriber.create({ data: { email: value, source: cleanSource } });
53	  } catch (err) {
54	    // Unique-constraint race: another request inserted the same email first.
55	    if (err instanceof Prisma.PrismaClientKnownRequestError && err.code === "P2002") {
56	      return {
57	        ok: true,
58	        status: "already",
59	        message: "You’re already on the list — thanks for sticking around!",
60	      };
61	    }
62	    return {
63	      ok: false,
64	      status: "error",
65	      message: "Something went wrong. Please try again in a moment.",
66	    };
67	  }
68	
69	  return {
70	    ok: true,
71	    status: "subscribed",
72	    message: "You’re in! We’ll send occasional product news — no spam.",
73	  };
74	}
