17	const MAX_PROMPT_CHARS = 2000;
18	const MIN_PROMPT_CHARS = 8;
19	// Cap how many builds a user may have in flight, and how many they can start in
20	// a short window, to keep API + SSH usage sane.
21	const MAX_ACTIVE_BUILDS_PER_USER = 3;
22	const RATE_WINDOW_MS = 60_000;
23	const MAX_BUILDS_PER_WINDOW = 5;
24	
25	// Statuses that mean a build is not yet finished (planning, awaiting approval,
26	// queued, or executing) — used for in-flight accounting.
27	const ACTIVE_STATUSES = ["QUEUED", "PLANNING", "AWAITING_APPROVAL", "RUNNING"] as const;
