29	export async function submitBuild(
30	  serverId: string,
31	  prompt: string
32	): Promise<{ error?: string; buildId?: string }> {
33	  const user = await requireUser();
34	
35	  // Feature flag: "Build with Claude" can be switched off platform-wide.
36	  if (!(await getSettingBool("feature_claude_builder", true))) {
37	    return { error: "Build with Claude is currently unavailable." };
38	  }
39	
40	  const clean = (prompt ?? "").trim();
41	  if (clean.length < MIN_PROMPT_CHARS) {
42	    return { error: "Please describe what you'd like Claude to build (a sentence or two)." };
43	  }
44	  if (clean.length > MAX_PROMPT_CHARS) {
45	    return { error: `Prompt is too long (max ${MAX_PROMPT_CHARS} characters).` };
46	  }
47	
48	  // BYOK gate: the owner must have an effective key (their own, or a platform fallback).
49	  const owner = await db.user.findUnique({
50	    where: { id: user.id },
51	    select: { anthropicKeyEnc: true },
52	  });
53	  if (!effectiveKeyFor(owner)) {
54	    return { error: "Connect your Anthropic API key to use Build with Claude." };
55	  }
56	
57	  // Ownership: the server must belong to this user.
58	  const server = await db.server.findFirst({ where: { id: serverId, userId: user.id } });
59	  if (!server) return { error: "Server not found." };
60	  if (server.status !== "RUNNING") {
61	    return { error: "The server must be running to build on it." };
62	  }
63	  if (!server.ipAddress || !server.rootPassword) {
64	    return { error: "This server isn't reachable yet — try again once it finishes provisioning." };
65	  }
66	
67	  // Rate sanity.
68	  const active = await db.claudeBuild.count({
69	    where: { userId: user.id, status: { in: [...ACTIVE_STATUSES] } },
70	  });
71	  if (active >= MAX_ACTIVE_BUILDS_PER_USER) {
72	    return { error: "You already have builds in progress. Wait for them to finish before starting another." };
73	  }
74	  const recent = await db.claudeBuild.count({
75	    where: { userId: user.id, createdAt: { gt: new Date(Date.now() - RATE_WINDOW_MS) } },
76	  });
77	  if (recent >= MAX_BUILDS_PER_WINDOW) {
78	    return { error: "Too many builds started just now — please wait a minute and try again." };
79	  }
80	  // One in-flight build per server keeps the SSH session serialized.
81	  const serverBusy = await db.claudeBuild.count({
82	    where: { serverId, status: { in: [...ACTIVE_STATUSES] } },
83	  });
84	  if (serverBusy > 0) {
85	    return { error: "A build is already in progress on this server." };
86	  }
87	
88	  const build = await db.claudeBuild.create({
89	    data: { userId: user.id, serverId, prompt: clean, status: "QUEUED", approved: false },
90	  });
91	
92	  // Enqueue the worker job; the handler reads the build via payload.buildId.
93	  // Because approved=false, the worker will PLAN (not execute).
94	  await db.job.create({
95	    data: { type: "CLAUDE_BUILD", serverId, payload: { buildId: build.id } },
96	  });
97	
98	  await db.auditLog
99	    .create({
100	      data: { userId: user.id, action: "server.claude_build", detail: `${serverId} ${build.id}` },
101	    })
102	    .catch(() => {});
103	
104	  revalidatePath("/dashboard/build");
105	  return { buildId: build.id };
106	}
