429	export async function topUp(prev: any, formData: FormData): Promise<{ error?: string }> {
430	  const user = await requireUser();
431	  // Security: never credit a wallet without a real payment. Once Stripe is
432	  // configured, the demo gateway is hard-disabled — top-ups must go through Checkout.
433	  const { stripeConfigured } = await import("./stripe");
434	  if (stripeConfigured()) {
435	    return { error: "Please add funds with a card via the secure checkout." };
436	  }
437	  const amount = Number(formData.get("amount"));
438	  if (!Number.isFinite(amount) || amount < 1 || amount > 1000) {
439	    return { error: "Amount must be between $1 and $1000." };
440	  }
441	  const cents = Math.round(amount * 100);
442	  // Enforce the admin-configured minimum top-up (`min_topup_cents`, default 500).
443	  const minTopup = await getSettingInt("min_topup_cents", 500);
444	  if (cents < minTopup) {
445	    return { error: `Minimum top-up is $${(minTopup / 100).toFixed(2)}.` };
446	  }
447	
448	  // Optional promo code: applied via the COUPON_COOKIE the billing CouponField
449	  // sets. applyCouponToTopup re-validates for this user against the real amount.
450	  const jar = await cookies();
451	  const couponCode = jar.get(COUPON_COOKIE)?.value?.trim();
452	  let bonusCents = 0;
453	  let couponId: string | null = null;
454	  let couponLabel = "";
455	  if (couponCode) {
456	    const result = await applyCouponToTopup(couponCode, cents);
457	    if (result.ok) {
458	      bonusCents = result.bonusCents;
459	      couponId = result.couponId;
460	      couponLabel = result.label;
461	    }
462	  }
463	
464	  await db.$transaction([
465	    db.user.update({
466	      where: { id: user.id },
467	      data: { balanceCents: { increment: cents + bonusCents } },
468	    }),
469	    db.walletTransaction.create({
470	      data: { userId: user.id, amountCents: cents, description: "Wallet top-up (demo gateway)" },
471	    }),
472	    ...(bonusCents > 0 && couponId
473	      ? [
474	          db.walletTransaction.create({
475	            data: {
476	              userId: user.id,
477	              amountCents: bonusCents,
478	              description: `Promo ${couponCode!.toUpperCase()} — ${couponLabel}`,
479	            },
480	          }),
481	          db.couponRedemption.create({
482	            data: { couponId, userId: user.id, amountCents: bonusCents, context: "topup" },
483	          }),
484	          db.coupon.update({
485	            where: { id: couponId },
486	            data: { timesRedeemed: { increment: 1 } },
487	          }),
488	        ]
489	      : []),
490	  ]);
491	  jar.delete(COUPON_COOKIE);
492	  await audit(user.id, "wallet.topup", `$${amount}${bonusCents > 0 ? ` +bonus $${(bonusCents / 100).toFixed(2)}` : ""}`);
